/* Text: antialiased glyph tables from include/font_aa.h, generated by
 * scripts/genfont.py.  Replacing the kernel's VGA bitmap font is the one
 * change here that every window can feel, so the cell was kept exactly
 * where the old one was: 16 rows, baseline on row 12, ink starting on
 * row 2 for a capital.  A caller positions a glyph by the top of its box
 * and nothing about the geometry of a menu, a title bar or a caret moves.
 *
 * Two designs share that cell:
 *
 *   ui / uib   proportional, one table per weight -- every GUI label,
 *              button, menu item and title.  Advances are the font's own,
 *              so "Task Manager" is narrower than the 8 pixels a character
 *              used to cost and text sits where it was centred to sit.
 *   mono       always 8 pixels -- the terminal, Notepad, path fields and
 *              Paint's text tool.  Anything whose caret maths counts
 *              columns needs the pen to land on col*8 every time.
 *
 * Coverage is one byte per pixel, so an edge pixel is a source-over
 * blend against whatever the compositor has already put there; the solid
 * case short-circuits to a store.  That is what makes a letter look like
 * type instead of like a stencil. */
#include "desktop.h"
#include <font_aa.h>

static const struct fa_glyph *g_ui(unsigned char ch, int bold)
{
    if (ch < 0x20 || ch > 0x7e) ch = '?';
    return &(bold ? fa_uib : fa_ui)[ch - 0x20];
}

static const struct fa_glyph *g_mono(unsigned char ch)
{
    if (ch < 0x20 || ch > 0x7e) ch = '?';
    return &fa_mono[ch - 0x20];
}

/* One glyph's ink, blended onto whatever is underneath.  `smear` is the
 * 1990s bold: draw the glyph, then draw it again one pixel to the right.
 * It stays only for font_draw(), whose callers pass 0 anyway -- the GUI
 * asks for the bold table instead. */
static void put(const struct fa_glyph *gl, int x, int y, u32 fg, int smear)
{
    if (!gl->w || !gl->h) return;
    int x0 = x + gl->x, y0 = y + gl->y;
    for (int r = 0; r < gl->h; r++) {
        const unsigned char *row = gl->cov + (size_t)r * gl->w;
        for (int c = 0; c < gl->w; c++) {
            int a = row[c];
            if (!a) continue;
            gfx_px_a(x0 + c, y0 + r, fg, a);
            if (smear) gfx_px_a(x0 + c + 1, y0 + r, fg, a);
        }
    }
}

/* ---- single glyphs: the fixed-cell half ---- */

void font_draw(int x, int y, unsigned char ch, u32 fg, int bold)
{
    put(g_mono(ch), x, y, fg, bold);
}

/* The advance a caller laying out by hand needs -- the splash logo
 * spaces its letters by this, times its magnification, rather than by
 * assuming a monospace width it no longer has. */
int font_adv(unsigned char ch)
{
    return g_ui(ch, 0)->adv;
}

void font_draw_bg(int x, int y, unsigned char ch, u32 fg, u32 bg)
{
    const struct fa_glyph *gl = g_mono(ch);
    gfx_fill(x, y, FA_MONO_W, FA_CELL_H, bg);
    put(gl, x, y, fg, 0);
}

/* A glyph blown up by a whole-number factor: the boot logo is type, not
 * art, so every source pixel becomes one coverage-coloured block at the
 * final size.  Blocks, not a resample, because at 5x each source pixel
 * is 25 destination pixels and a smooth ramp between them is exactly
 * what an antialiased edge already is. */
void font_draw_scale(int x, int y, unsigned char ch, u32 fg, int scale)
{
    if (scale < 1) scale = 1;
    const struct fa_glyph *gl = g_ui(ch, 0);
    if (!gl->w || !gl->h) return;
    int x0 = x + gl->x * scale, y0 = y + gl->y * scale;
    for (int r = 0; r < gl->h; r++) {
        const unsigned char *row = gl->cov + (size_t)r * gl->w;
        for (int c = 0; c < gl->w; c++) {
            if (!row[c]) continue;
            gfx_fill_a(x0 + c * scale, y0 + r * scale, scale, scale, fg, row[c]);
        }
    }
}

/* A glyph into a buffer the caller owns -- Paint's canvas, which is not
 * the screen and so cannot be reached by gfx_px().  Same table as
 * font_draw(), because what lands on the canvas has to line up with the
 * caret that walked across it; the bounds are the buffer's, not the clip
 * rect's, because nothing here knows where the window that owns it will
 * end up. */
void font_draw_buf(u32 *dst, int dw, int dh, int pitch, int x, int y,
                   unsigned char ch, u32 fg)
{
    const struct fa_glyph *gl = g_mono(ch);
    if (!gl->w || !gl->h) return;
    for (int r = 0; r < gl->h; r++) {
        int yy = y + gl->y + r;
        if (yy < 0 || yy >= dh) continue;
        const unsigned char *row = gl->cov + (size_t)r * gl->w;
        for (int c = 0; c < gl->w; c++) {
            int xx = x + gl->x + c;
            if (xx < 0 || xx >= dw) continue;
            int a = row[c];
            if (!a) continue;
            u32 *p = &dst[(size_t)yy * pitch + xx];
            *p = a >= 255 ? fg : gfx_over(*p, fg, a);
        }
    }
}

/* ---- strings ---- */

int gfx_strw(const char *s)
{
    int w = 0;
    for (; *s; s++) w += g_ui((unsigned char)*s, 0)->adv;
    return w;
}

int gfx_strw_bold(const char *s)
{
    int w = 0;
    for (; *s; s++) w += g_ui((unsigned char)*s, 1)->adv;
    return w;
}

void gfx_text(int x, int y, const char *s, u32 fg)
{
    for (; *s; s++) {
        const struct fa_glyph *gl = g_ui((unsigned char)*s, 0);
        put(gl, x, y, fg, 0);
        x += gl->adv;
    }
}

/* Real bold, from the second table -- not the old draw-it-twice smear,
 * which at this size left a grey fringe round every stem. */
void gfx_text_bold(int x, int y, const char *s, u32 fg)
{
    for (; *s; s++) {
        const struct fa_glyph *gl = g_ui((unsigned char)*s, 1);
        put(gl, x, y, fg, 0);
        x += gl->adv;
    }
}

/* Fixed-cell strings: one glyph per 8 pixels, no matter how narrow the
 * glyph is.  The terminal pads every line to `cols` characters before it
 * calls this, so the rows of a directory listing still line up. */
void gfx_text_mono(int x, int y, const char *s, u32 fg)
{
    for (; *s; s++) {
        put(g_mono((unsigned char)*s), x, y, fg, 0);
        x += FA_MONO_W;
    }
}

void gfx_text_bg(int x, int y, const char *s, u32 fg, u32 bg)
{
    for (; *s; s++) {
        const struct fa_glyph *gl = g_ui((unsigned char)*s, 0);
        gfx_fill(x, y, gl->adv, FA_CELL_H, bg);
        put(gl, x, y, fg, 0);
        x += gl->adv;
    }
}

/* Draw at most maxw pixels, replacing the tail with "..." when the
 * string does not fit.  Used by title bars and list rows, where clipping
 * mid-glyph looks like a rendering bug.  Widths are the font's own now,
 * so the test is pixels rather than characters. */
void gfx_text_w(int x, int y, const char *s, u32 fg, int maxw)
{
    if (gfx_strw(s) <= maxw) {
        gfx_text(x, y, s, fg);
        return;
    }
    int dots = g_ui('.', 0)->adv * 3;
    int used = 0, keep = 0;
    for (const char *p = s; *p; p++) {
        int a = g_ui((unsigned char)*p, 0)->adv;
        if (used + a + dots > maxw) break;
        used += a;
        keep++;
    }
    if (keep < 1) keep = 1;
    for (int i = 0; i < keep && s[i]; i++) {
        const struct fa_glyph *gl = g_ui((unsigned char)s[i], 0);
        put(gl, x, y, fg, 0);
        x += gl->adv;
    }
    const struct fa_glyph *dot = g_ui('.', 0);
    for (int i = 0; i < 3; i++) {
        put(dot, x, y, fg, 0);
        x += dot->adv;
    }
}
